CREATE TABLE public.demographic_area_profiles (
  sa2_code_2021 TEXT NOT NULL,
  reference_year INTEGER NOT NULL,
  sa2_name_2021 TEXT NOT NULL,
  geography_level TEXT NOT NULL DEFAULT 'SA2',
  boundary_edition TEXT NOT NULL DEFAULT 'ASGS Edition 3 SA2 2021',
  census_total_population NUMERIC,
  age_65_plus_count NUMERIC,
  age_65_plus_percent NUMERIC,
  age_75_plus_count NUMERIC,
  age_75_plus_percent NUMERIC,
  under_five_count NUMERIC,
  under_five_percent NUMERIC,
  need_assistance_count NUMERIC,
  need_assistance_percent NUMERIC,
  no_vehicle_dwellings_count NUMERIC,
  vehicle_response_dwellings_count NUMERIC,
  no_vehicle_dwellings_percent NUMERIC,
  seifa_irsd_score NUMERIC,
  seifa_irsd_state_decile NUMERIC,
  seifa_irsd_state_percentile NUMERIC,
  seifa_ier_score NUMERIC,
  seifa_ier_state_decile NUMERIC,
  seifa_ier_state_percentile NUMERIC,
  census_source_id UUID NOT NULL REFERENCES public.dispensing_demographic_sources(id),
  seifa_source_id UUID NOT NULL REFERENCES public.dispensing_demographic_sources(id),
  coverage_status TEXT NOT NULL CHECK (coverage_status IN ('complete','partial','unavailable')),
  missing_reasons JSONB NOT NULL DEFAULT '[]'::jsonb,
  retrieved_at TIMESTAMPTZ NOT NULL DEFAULT '2026-07-29T04:30:00Z',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (sa2_code_2021,reference_year),
  FOREIGN KEY (sa2_code_2021) REFERENCES public.dispensing_population_areas(sa2_code_2021),
  CHECK (age_65_plus_percent IS NULL OR age_65_plus_percent BETWEEN 0 AND 100),
  CHECK (age_75_plus_percent IS NULL OR age_75_plus_percent BETWEEN 0 AND 100),
  CHECK (under_five_percent IS NULL OR under_five_percent BETWEEN 0 AND 100),
  CHECK (need_assistance_percent IS NULL OR need_assistance_percent BETWEEN 0 AND 100),
  CHECK (no_vehicle_dwellings_percent IS NULL OR no_vehicle_dwellings_percent BETWEEN 0 AND 100)
);

ALTER TABLE public.demographic_area_profiles ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.demographic_area_profiles TO anon,authenticated;
GRANT ALL ON public.demographic_area_profiles TO service_role;
CREATE POLICY public_reads_official_demographic_profiles
  ON public.demographic_area_profiles FOR SELECT TO anon,authenticated USING (true);

