  vehicle_response_dwellings_count=EXCLUDED.vehicle_response_dwellings_count,
  no_vehicle_dwellings_percent=EXCLUDED.no_vehicle_dwellings_percent,
  seifa_irsd_score=EXCLUDED.seifa_irsd_score,
